function subscribe(){if(st.rt)sb.removeChannel(st.rt);
 st.rt=sb.channel('admin-rt')
  .on('postgres_changes',{event:'*',schema:'public',table:'conversations'},onConv)
  .on('postgres_changes',{event:'INSERT',schema:'public',table:'messages'},p=>onMsg(p.new))
  .on('postgres_changes',{event:'*',schema:'public',table:'admin_reviews'},onRev).subscribe()}
function onConv(p){const row=p.new,old=p.old;
 if(p.eventType==='DELETE'){st.convs=st.convs.filter(c=>c.id!==old.id);if(st.active===old.id)st.active=null}
 else{const i=st.convs.findIndex(c=>c.id===row.id);if(i<0)st.convs.push(row);else st.convs[i]=row;
  if(row.id===st.active&&row.unread_count>0&&st.view==='chats'&&!document.hidden)markRead(row.id)}
 st.convs.sort((a,b)=>b.last_message_at.localeCompare(a.last_message_at));updBadges();if(st.view==='chats')renderList()}
function onMsg(m){
 if(m.conversation_id===st.active&&st.view==='chats'){appendMsg(m);if(m.sender==='visitor'){if(document.hidden)notify('Новое сообщение',m.body||'📷 Фото');else markRead(m.conversation_id)}}
 else if(m.sender==='visitor'){const c=st.convs.find(c=>c.id===m.conversation_id);notify((c?c.alias:'Аноним')+' пишет',m.body||'📷 Фото')}}
function onRev(p){const row=p.new;
 if(p.eventType==='DELETE')st.rev=st.rev.filter(r=>r.id!==p.old.id);
 else{const i=st.rev.findIndex(r=>r.id===row.id);if(i<0){st.rev.unshift(row);if(p.eventType==='INSERT')notify('Новый отзыв',row.author_name+': '+row.body.slice(0,80))}else st.rev[i]=row;
  if(p.eventType==='INSERT'&&row.status==='pending')sb.from('admin_reviews').update({status:'published'}).eq('id',row.id).then(({error})=>{if(error)toast('Не удалось автоматически опубликовать отзыв: '+explain(error));else{row.status='published';if(st.view==='reviews')renderReviews()}})}
 st.rev.sort((a,b)=>b.created_at.localeCompare(a.created_at));updBadges();if(st.view==='reviews')renderReviews()}
