async function loadMsgs(id){
 const{data}=await sb.from('messages').select('*').eq('conversation_id',id).order('id',{ascending:false}).limit(300);
 if(st.active!==id)return;const box=$('#msgs');if(!box)return;box.replaceChildren();lastDay='';(data||[]).reverse().forEach(m=>appendMsg(m,1));box.scrollTop=box.scrollHeight;markRead(id)}
let lastDay='';
function appendMsg(m,quiet){const box=$('#msgs');if(!box)return;if(box.querySelector('[data-id="'+m.id+'"]'))return;
 const d=dm(m.created_at);if(d!==lastDay){lastDay=d;box.append(h('div',{class:'day',text:d===dm(new Date().toISOString())?'Сегодня':d}))}
 const mine=m.sender==='admin',near=box.scrollHeight-box.scrollTop-box.clientHeight<160;
 const el=h('div',{class:'m '+(mine?'a':'v'),'data-id':m.id},mine?h('span',{class:'nx',text:m.admin_name||'Админ'}):null);
 if(m.image_path){const im=h('img',{alt:''});el.append(im);signed(m.image_path).then(u=>{if(u){im.src=u;im.onclick=()=>zoom(u)}})}
 if(m.body)el.append(h('div',{class:'bb',text:m.body}));el.append(h('span',{class:'tx',text:hm(m.created_at)}));box.append(el);
 if(!quiet&&(near||mine))box.scrollTop=box.scrollHeight}
function renderThread(){const t=$('#thread');if(!t)return;const c=st.convs.find(c=>c.id===st.active);
 if(!c){t.replaceChildren(h('div',{class:'empty',text:'Выбери диалог слева'}));return}
 st.att=null;
 const ta=h('textarea',{rows:1,placeholder:'Ответить анонимно…',maxlength:4000}),file=h('input',{type:'file',accept:'image/*',hidden:true}),prev=h('div',{class:'cprev',hidden:true}),send=h('button',{class:'ibtn send','aria-label':'Отправить',onclick:doSend},ic('send'));
 ta.oninput=()=>{ta.style.height='auto';ta.style.height=Math.min(ta.scrollHeight,160)+'px'};
 ta.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&matchMedia('(hover:hover)').matches){e.preventDefault();doSend()}};
 function showAtt(){prev.replaceChildren();prev.hidden=!st.att;if(!st.att)return;prev.append(h('img',{src:st.att.url,alt:''}),h('button',{class:'ibtn',onclick:()=>{URL.revokeObjectURL(st.att.url);st.att=null;showAtt()}},ic('x')))}
 file.onchange=async()=>{const f=file.files[0];file.value='';if(!f)return;if(!/^image\//.test(f.type))return toast('Выбери изображение');try{const b=await compress(f);if(st.att)URL.revokeObjectURL(st.att.url);st.att={blob:b,url:URL.createObjectURL(b)};showAtt()}catch(e){toast('Не удалось прочитать фото')}};
 let busy=0;async function doSend(){const text=ta.value.trim();if((!text&&!st.att)||busy)return;busy=1;send.disabled=true;
  try{let path=null;if(st.att){path=c.id+'/'+uuid()+'.jpg';const r=await sb.storage.from('chat-images').upload(path,st.att.blob,{contentType:'image/jpeg',cacheControl:'3600'});if(r.error)throw r.error}
   const{data,error}=await sb.from('messages').insert({conversation_id:c.id,sender:'admin',body:text||null,image_path:path}).select().single();if(error)throw error;
   appendMsg(data);ta.value='';ta.style.height='';if(st.att){URL.revokeObjectURL(st.att.url);st.att=null;showAtt()}}
  catch(e){toast(explain(e))}busy=0;send.disabled=false;ta.focus()}
 const isOwner=st.me.role==='owner';
 t.replaceChildren(
  h('div',{class:'th'},h('button',{class:'ibtn back',onclick:()=>{st.active=null;$('#chats').classList.remove('has-active');renderList();renderThread()},'aria-label':'Назад'},ic('back')),
   h('div',{class:'tt'},h('b',{text:c.alias}),h('small',{text:'анонимный посетитель · с '+dm(c.created_at)})),
   h('button',{class:'btn sm',onclick:async()=>{const ns=c.status==='open'?'closed':'open';const{error}=await sb.from('conversations').update({status:ns}).eq('id',c.id);if(error)return toast(explain(error));c.status=ns;renderList();renderThread()}},c.status==='open'?'Закрыть':'Открыть снова'),
   isOwner?h('button',{class:'ibtn',title:'Удалить диалог','aria-label':'Удалить',onclick:async()=>{if(!confirm('Удалить диалог и все сообщения?'))return;const{error}=await sb.from('conversations').delete().eq('id',c.id);if(error)return toast(explain(error));st.convs=st.convs.filter(x=>x.id!==c.id);st.active=null;updBadges();renderChats()}},ic('trash')):null),
  h('div',{class:'msgs',id:'msgs'}),
  h('div',{class:'comp'},prev,h('div',{class:'crow'},h('button',{class:'ibtn','aria-label':'Фото',onclick:()=>file.click()},ic('img')),ta,send,file)));
 if(matchMedia('(hover:hover)').matches)ta.focus();loadMsgs(c.id)}

