(async()=>{
 if(!cfgOk){app.replaceChildren(h('div',{class:'auth'},h('div',{class:'card'},h('div',{class:'logo'},'RaevYoU',h('small',{text:'admin'})),h('h1',{text:'Supabase не подключён'}),h('p',{text:'Открой script.js и впиши Project URL и anon key в самом верху файла (две строки). Затем настрой базу — кнопка ниже.'}),h('button',{class:'btn pri',onclick:sqlModal},'SQL для настройки Supabase'))));return}
 try{await loadSdk();sb=window.supabase.createClient(C.url||'demo',C.key||'demo',{auth:{storageKey:'rv-admin-auth',persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}})}
 catch(e){app.replaceChildren(h('div',{class:'auth'},h('div',{class:'card'},h('h1',{text:'Нет соединения'}),h('p',{text:'Не удалось загрузить библиотеку Supabase. Проверь интернет и обнови страницу.'}))));return}
 try{await boot()}catch(e){authScreen('login','Ошибка: '+explain(e))}
})();
